package cn.balltv.portal;
import android.content.*;import org.json.*;import java.util.*;
public final class Library {
    public static String view(Feeds.Match m){return m.kind.equals("replay")?"replay":m.raw.has("match")||m.raw.has("archors")?"schedule":"live";}
    public static JSONArray records(Events.Group group)throws Exception{JSONArray a=new JSONArray();for(Feeds.Match m:group.members)a.put(new JSONObject().put("source",m.source).put("view",view(m)).put("raw",m.raw));return a;}
    public static ArrayList<Feeds.Match> decode(JSONArray records){ArrayList<Feeds.Match> result=new ArrayList<Feeds.Match>();for(int i=0;i<records.length();i++)try{JSONObject o=records.getJSONObject(i);result.addAll(Feeds.parse(o.getString("source"),o.optString("view","live"),new JSONObject().put("data",new JSONArray().put(o.getJSONObject("raw")))).items);}catch(Exception ignored){}return result;}
    static JSONArray list(Context c,String key){try{return new JSONArray(c.getSharedPreferences("matches",0).getString(key,"[]"));}catch(Exception e){return new JSONArray();}}
    public static ArrayList<Feeds.Match> load(Context c,String key){ArrayList<Feeds.Match> out=new ArrayList<Feeds.Match>();JSONArray a=list(c,key);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;JSONArray records=o.optJSONArray("members");out.addAll(decode(records==null?new JSONArray().put(o):records));}return out;}
    public static boolean favorite(Context c,Events.Group group){for(Events.Group g:Events.group(load(c,"saved")))if(g.id.equals(group.id))return true;return false;}
    public static boolean toggle(Context c,Events.Group group)throws Exception{boolean remove=favorite(c,group);JSONArray a=list(c,"saved"),out=new JSONArray();Set<String> keys=new HashSet<String>();for(Feeds.Match m:group.members)keys.add(m.key());for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);boolean same=group.id.equals(o.optString("id"));if(!same&&o.has("source")){ArrayList<Feeds.Match> old=decode(new JSONArray().put(o));if(!old.isEmpty())same=keys.contains(old.get(0).key())||Events.group(old).get(0).id.equals(group.id);}if(!same)out.put(o);}if(!remove)out.put(new JSONObject().put("id",group.id).put("members",records(group)));c.getSharedPreferences("matches",0).edit().putString("saved",out.toString()).apply();return !remove;}
    public static void remember(Context c,Events.Group group)throws Exception{JSONArray a=list(c,"history"),out=new JSONArray();out.put(new JSONObject().put("id",group.id).put("at",System.currentTimeMillis()).put("members",records(group)));for(int i=0;i<a.length()&&out.length()<30;i++){JSONObject o=a.getJSONObject(i);if(!group.id.equals(o.optString("id")))out.put(o);}c.getSharedPreferences("matches",0).edit().putString("history",out.toString()).apply();}
}
